            }
        }
        [Test] public void CounterDeferredPreviewHoldRejectsChangedIdentityOrProducerWithoutChangingLedger()
        {
            foreach(var change in new[]{"foreign","life","claim","producer","throw"})
            {
                var f=new CounterAdvanceReadinessModel(previewPriority:true);Assert.That(f.Attach(),Is.True);f.Run();f.LosePriorityPreview();
                if(change=="life" || change=="claim")f.PublishPriority(change=="life"?new object():null,change=="claim");
                if(change=="producer")f.Current=false;
                if(change=="throw")f.ReadCurrent=()=>throw new InvalidOperationException("readonly producer unavailable");
                var original=f.Core.GetDecision(f.Incoming);var supplied=change=="foreign"?new TrafficDecision(original.Intent,original.Kind,original.Reason):original;
                var ledger=D3CaptureAccounting(f.Core,f.Incoming);Assert.That(HoldProducerPreview(f.Core,supplied),Is.False,change);
                D3AssertAccounting(f.Core,f.Incoming,ledger);Assert.That(D1Read(f.Core,f.Incoming,"ProducerPreviewHeld"),Is.False);
            }
        }
        [Test] public void CounterDeferredPreviewHoldRejectsSameReceiverReentryWithoutRenewingDebt()
        {
            var f=new CounterAdvanceReadinessModel(previewPriority:true);Assert.That(f.Attach(),Is.True);f.Run();f.LosePriorityPreview();
            var original=f.Core.GetDecision(f.Incoming);var reads=0;var nested=true;
            f.ReadCurrent=()=>{reads++;if(reads==1)nested=HoldProducerPreview(f.Core,original);return true;};
            Assert.That(HoldProducerPreview(f.Core,original),Is.True,"RED: outer authentic finite hold");
            Assert.That(nested,Is.False);Assert.That(reads,Is.EqualTo(1),"Same receiver must reject before reentering the producer reader");
            Assert.That(D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(10f));Assert.That(f.Core.QueriesConsumed(f.Incoming),Is.Zero);
        }

        [TestCase(true)][TestCase(false)]
        public void CounterAdvanceReadinessDefersBothOriginalBirthOrdersWithoutNewRightsOrQueries(bool predecessorFirst)
        {
            var f=new CounterAdvanceReadinessModel(predecessorFirst);Assert.That(f.Attach(),Is.True);
            if(!predecessorFirst)f.CommitHeadParking(); // follower is already submitted/queued before the actual owner commit.
            var before=f.Calls;var entry=D1Read(f.Core,f.Incoming,"Key");var first=D1Read(f.Core,f.Incoming,"FirstFrame");
            f.Run();f.AssertHeld();var sequence=f.Core.GetDecision(f.Incoming).RequestSequence;
            var consumed=f.Core.QueriesConsumed(f.Incoming);var remaining=(float)D1Read(f.Core,f.Incoming,"WaitRemaining");
            f.Core.Tick(.25f,false);for(var frame=2;frame<=4;frame++){f.Run(frame);f.AssertHeld();}
            Assert.That(f.Calls,Is.EqualTo(before),"No unchanged readiness polling may call Native");
            Assert.That(f.Core.QueriesConsumed(f.Incoming),Is.EqualTo(consumed));Assert.That(consumed,Is.Zero);
            Assert.That(D1Read(f.Core,f.Incoming,"FirstFrame"),Is.EqualTo(first));Assert.That(D1Read(f.Core,f.Incoming,"Key"),Is.EqualTo(entry));
            Assert.That(f.Core.GetDecision(f.Incoming).RequestSequence,Is.EqualTo(sequence));
            Assert.That((float)D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(remaining-.25f).Within(.0001));
            f.CancelUnusedParking();Assert.That(f.Run(5).Kind,Is.EqualTo(TrafficDecisionKind.Granted));
            Assert.That(f.Core.GetDecision(f.Incoming).RequestSequence,Is.EqualTo(sequence));Assert.That(D1Read(f.Core,f.Incoming,"FirstFrame"),Is.EqualTo(first));
        }
        [Test] public void CounterAdvanceReadinessIdleParkingCannotBorrowCashierWaitingAuthority()
        {
            var f=new CounterAdvanceReadinessModel();f.WorkingSeconds=0;Assert.That(f.Attach(),Is.True);
            var d=f.Run();Assert.That(d.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(d.Reason,Is.EqualTo("no-independent-finite-release-or-cycle"));
            Assert.That(d.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));Assert.That(f.Core.HasActiveGrant(f.Incoming),Is.False);
        }
        [Test] public void CounterAdvanceReadinessPauseAndExpiryKeepTheOriginalFiniteBudget()
        {
            var f=new CounterAdvanceReadinessModel();Assert.That(f.Attach(),Is.True);f.Run();f.AssertHeld();
            var remaining=(float)D1Read(f.Core,f.Incoming,"WaitRemaining");f.Core.Tick(100,true);f.AssertHeld();
            Assert.That((float)D1Read(f.Core,f.Incoming,"WaitRemaining"),Is.EqualTo(remaining));f.Core.Tick(remaining,false);
            var terminal=f.Core.GetDecision(f.Incoming);Assert.That(terminal.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(terminal.Reason,Is.EqualTo("wait-budget-exhausted"));f.CancelUnusedParking();f.Run(2);
