        [TestCase("invalid")][TestCase("throw")][TestCase("null")][TestCase("snapshot-reentry")]
        public void AdmissionReadinessFailedProducerReadCannotBecomeAnEmptyExitList(string fault)
        {
            var f=new AdmissionExitReadinessModel();
            Func<IReadOnlyList<TrafficIntentKey>> read=()=>{
                if(fault=="throw")throw new InvalidOperationException("Modeled producer read failure");
                if(fault=="snapshot-reentry")f.Core.SetSnapshot(World(2,2,actors:f.Snapshot.Bodies.ToArray()));
                return fault=="null"?null:new[]{f.Leaving};};
