            Assert.That(D1Read(f.Core,f.Key,"Jobs"),Is.SameAs(jobs));Assert.That(D1Read(f.Core,f.Key,"JourneyPermit"),Is.SameAs(permit));Assert.That(f.Core.QueriesConsumed(f.Key),Is.EqualTo(q));
            Assert.That(jobs.Count,Is.EqualTo(originalJobs.Length),"The same IList must not conceal cleared owned jobs");
