            Assert.That((Vector3[])D1Read(f.Core,f.Key,"CurrentPath"),Is.EqualTo(originalPath),"Current owned geometry must remain intact");
            Assert.That(D1Read(f.Core,f.Key,"Journey"),Is.SameAs(journey));
            Assert.That((Vector3[])D1Read(f.Core,f.Key,"Journey"),Is.EqualTo(originalJourney),"Selected owned journey must remain intact");
        }
