        [Test] public void FiniteBusinessBodyWithNoDetourKeepsOriginalFiniteWaitAndDoesNotSearchWhileAsleep()
        {
            var f=new FiniteBusinessGeometryModel(narrow:true);var waiting=f.Finish();var calls=f.Calls;
            Assert.That(waiting.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(waiting.Blockers.Single().Owner,Is.EqualTo(f.Worker));
            Assert.That((float)D1Read(f.Core,f.Key,"WaitRemaining"),Is.EqualTo(8));
