        }

        [TestCase(false)]
        [TestCase(true)]
        public void DuplicateCanonicalParkingCannotShrinkPhysicalUnionQueryTargets(bool smallerCanonicalClearance)
        {
            // Geometry fixture informed by Native evidence; decimal coordinates are not a float-bit replay.
            // 同物理并集的black-box模型；不替代真实Native RED，不构造移动权限或调用private Job。
            var start=P(-1.5f,.5f);var goal=P(.5f,-3.35f);const float radius=.45f,margin=.011f;
            var positions=new[]{P(-2.6f,-1.7f),P(-2.6f,-2.8f),P(-1.5f,-2.8f),P(-1.5f,-1.656289f),P(1.5f,2.5f),P(-2.5f,2.5f)};
            var owners=Enumerable.Range(0,positions.Length).Select(i=>Key("seed-obstacle-"+i,"body")).ToArray();
            var lives=positions.Select(_=>new object()).ToArray();var mover=Key("seed-exit","actual-exit");var moverLife=new object();
            var pickup=new PickupQueueService(positions.Take(4).ToArray(),new[]{start});
            for(var i=0;i<4;i++)
            {
                Assert.That(pickup.TryReserve(owners[i].ActorId,out _),Is.True);
                Assert.That(pickup.TryBeginTransfer(owners[i].ActorId,out var paid),Is.True);
                Assert.That(pickup.MarkArrived(owners[i].ActorId,paid.Generation),Is.True);
            }
            var claims=new PickupQueueService.ReservationClaim[4];var parking=new TrafficParkingFact[4];
            var parkingRadius=smallerCanonicalClearance ? .35f : radius;
            for(var i=0;i<parking.Length;i++)
            {
                Assert.That(pickup.TryCaptureReservation(owners[i].ActorId,out claims[i]),Is.True);Assert.That(claims[i].IsCurrent,Is.True);
                Assert.That(claims[i].Assignment.Arrived,Is.True);Assert.That(claims[i].Assignment.Position,Is.EqualTo(positions[i]));
                parking[i]=new TrafficParkingFact(owners[i],pickup,pickup.Version,"pickup/"+owners[i].ActorId,positions[i],parkingRadius,margin,semanticCheckpoint:claims[i]);
            }
            var bodies=positions.Select((point,i)=>new TrafficBodyFact(owners[i],point,radius,independentlyProgressing:false,
                remainingSeconds:0,safetyMargin:margin,actorLife:lives[i])).Concat(new[]{
                    new TrafficBodyFact(mover,start,radius,independentlyProgressing:false,remainingSeconds:0,safetyMargin:margin,actorLife:moverLife)}).ToArray();
            var controlWorld=World(actors:bodies);var repeatedWorld=World(actors:bodies,parking:parking);
            for(var i=0;i<parking.Length;i++)
            {
                Assert.That(parking[i].Owner,Is.EqualTo(bodies[i].Owner));Assert.That(parking[i].Position,Is.EqualTo(bodies[i].Position));
                Assert.That(parking[i].CanonicalOwner,Is.SameAs(pickup));Assert.That(parking[i].SemanticCheckpoint,Is.SameAs(claims[i]));
                Assert.That(parking[i].OwnerVersion,Is.EqualTo(pickup.Version));Assert.That(repeatedWorld.Bodies[i].ActorLife,Is.SameAs(controlWorld.Bodies[i].ActorLife));
                var bodyClearance=radius+bodies[i].Radius+Mathf.Max(margin,bodies[i].SafetyMargin);
                var parkingClearance=radius+parking[i].Radius+Mathf.Max(margin,parking[i].SafetyMargin);
                Assert.That(parkingClearance,Is.LessThanOrEqualTo(bodyClearance),"The unchanged body is the maximum-clearance physical union at this exact position");
                if(smallerCanonicalClearance)Assert.That(parkingClearance,Is.LessThan(bodyClearance),"Smaller parking appears first in MovementObstacles; first-entry deduplication must not lower the max union");
            }
            var frozenDirect=Array.AsReadOnly(new[]{new Vector3(-1.5f,.0125f,.5f),new Vector3(-1.45f,.0125f,-1.025f),
                new Vector3(-1.325f,.0125f,-1.275f),new Vector3(.5f,.0125f,-3.35f)});
            Assert.That(CustomerRoutePlanner.IsClear(frozenDirect,positions,2*radius+margin),Is.False,
                "PREMISE: the common complete direct path hits a real stationary body, so both public requests really enter bounded candidate search");
            const int frameBudget=128,intentBudget=16384;const int originalSeedLimit=8;
            var maxQueryTargets=1+originalSeedLimit*2*8; // Goal plus the unchanged eight seeds' two octagonal rings.
            HashSet<Vector3> QueryTargets(TrafficWorldSnapshot world,string label)
            {
                var targets=new HashSet<Vector3>();var calls=0;var directCalls=0;
                IReadOnlyList<Vector3> Provider(Vector3 from,Vector3 to)
                {
                    calls++;targets.Add(to);
                    if(from.Equals(start) && to.Equals(goal)){directCalls++;return frozenDirect;}
                    return null; // Every other modeled Native edge is unavailable; never manufacture a successful detour.
                }
                var core=Coordinator(world,frameBudget:frameBudget,intentBudget:intentBudget,query:Provider);
                var request=new TrafficRequest(mover,11,world,start,goal,radius,"pickup/"+mover.ActorId,safetyMargin:margin,planPrimaryRoute:true);
                core.EvaluateMovement(request);
                // At most 129 query targets under the unchanged seed limit; two original 128-query frames suffice.
                for(var frame=11;frame<=12;frame++)
                {
                    core.ProcessReady(frame);Assert.That(core.QueriesThisFrame,Is.LessThanOrEqualTo(frameBudget));
                    if(core.GetDecision(mover).Kind!=TrafficDecisionKind.DeferredByBudget)break;
                }
                var decision=core.GetDecision(mover);
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),label+": "+decision.Reason);
                Assert.That(decision.Reason,Is.EqualTo("bounded-route-proof-failed"));Assert.That(decision.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
                Assert.That(decision.AcquiredSequence,Is.Zero);Assert.That(core.HasActiveGrant(mover),Is.False);Assert.That(core.TryGetCommittedJourney(mover,out _),Is.False);
                Assert.That(directCalls,Is.EqualTo(1));Assert.That(calls,Is.GreaterThan(1),"The initial nonnull blocked path must actually trigger original candidate queries");
                Assert.That(core.QueriesConsumed(mover),Is.EqualTo(calls));Assert.That(calls,Is.LessThanOrEqualTo(intentBudget));Assert.That(targets.Count,Is.LessThanOrEqualTo(maxQueryTargets));
                TestContext.WriteLine("PHYSICAL_UNION_QUERY_TARGETS label="+label+" smallerCanonical="+smallerCanonicalClearance+" calls="+calls+" targets="+targets.Count+
                    " result="+decision.Kind+"/"+decision.Reason+" acquisition=0 targets=["+string.Join(";",targets.OrderBy(p=>p.x).ThenBy(p=>p.z).Select(p=>p.ToString("F9")))+"]");
                return targets;
            }
            var control=QueryTargets(controlWorld,"six-stationary-bodies");var repeated=QueryTargets(repeatedWorld,"same-union-plus-four-real-canonical-claims");
            foreach(var claim in claims)Assert.That(claim.IsCurrent,Is.True,"No model run changes the original canonical queue ownership");
            CollectionAssert.AreEquivalent(control,repeated,
                "RED: redundant canonical/body facts must preserve the public query-target set of their per-position maximum-clearance physical union, without expanding the original eight seeds or query budgets");
        }

        private static readonly Vector3 Origin = Vector3.zero;
        private static Vector3 P(float x, float z = 0) => new Vector3(x, 0, z);
        private static TrafficIntentKey Key(string actor, string phase = "journey", int generation = 1,
            int layout = 7, long epoch = 1, string session = "scene")
            => new TrafficIntentKey(session, epoch, actor, phase, generation, layout, "order.1");
        [TestCase("blocked")] [TestCase("clear")] [TestCase("body-only")]
        public void FiniteBodyHintCannotOverrideCurrentBoundRouteBlockedByAPhysicalBody(string mode)
        {
            var known=mode!="body-only";
            var owner=Key("authoritative-finite-owner",known?"pickup-paid-movement":"body");
            var incoming=Key("authoritative-fallback-waiter","parking");var obstacle=Key("authoritative-route-obstacle","body");
            var ownerLife=new object();var waiterLife=new object();var obstacleLife=new object();
            var from=known?P(2,-3):P(2);var goal=P(2,3);var target=P(2);
            var resource=known?"pickup/"+owner.ActorId:"body";
            TrafficWorldSnapshot Snapshot(int version,bool changed)
            {
                var pose=from+(changed?Vector3.forward*.1f:Vector3.zero);
                var bodies=new List<TrafficBodyFact>{
                    new TrafficBodyFact(owner,pose,.4f,independentlyProgressing:true,remainingSeconds:changed?12.5f:13f,actorLife:ownerLife),
                    new TrafficBodyFact(incoming,Origin,.4f,actorLife:waiterLife)};
                if(changed)bodies.Add(new TrafficBodyFact(obstacle,mode=="blocked"?P(2,1):P(5,1),.4f,actorLife:obstacleLife));
                return World(version,version,bodies.ToArray());
            }
            var world=Snapshot(1,false);var calls=0;
            var core=Coordinator(world,waitSeconds:30,query:(a,b)=>{calls++;return new[]{a,b};});
            TrafficDecision source=null;object originalLeg=null;var stamp=new TrafficNativeStamp(9711,1);
            if(known)
            {
                source=Grant(core,Request(owner,from,goal,world,frame:1,resource:resource,seconds:13));
                core.PrepareLeg(source,resource,0,ownerLife,1,world,from,.05f,2);core.ProcessReady(2);
                Assert.That(core.TryCommit(core.GetDecision(owner)),Is.True);Assert.That(core.BindLeg(owner,ownerLife,stamp),Is.True);
                originalLeg=D1Read(core,owner,"Leg");
                Assert.That(D3ReadField(originalLeg,"Committed"),Is.EqualTo(true));Assert.That(D3ReadField(originalLeg,"Bound"),Is.EqualTo(true));
                Assert.That(D3ReadField(originalLeg,"Completed"),Is.EqualTo(false));Assert.That(core.HasActiveGrant(owner),Is.True);
            }
            else Assert.That(((System.Collections.IDictionary)D3ReadField(core,"entries")).Contains(owner),Is.False,
                "CONTROL: caller-owned finite business/body facts have no known Core route to contradict");
            var request=Request(incoming,Origin,target,world,frame:11,resource:"prospective-parking",seconds:20);
            core.EvaluateParking(request);core.ProcessReady(11);var original=core.GetDecision(incoming);
            Assert.That(original.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),"PREMISE: initial clear source supplies the real original finite WAIT: "+original.Reason);
            Assert.That(original.Blockers.Any(b=>b.Owner.Equals(owner)&&b.ResourceId==resource),Is.True);
            var entry=((System.Collections.IDictionary)D3ReadField(core,"entries"))[incoming];
            var frozen=D1Read(core,incoming,"FrozenOwners");var pool=D1Read(core,incoming,"FrozenResources");
            var age=D1Read(core,incoming,"FirstFrame");var sequence=original.RequestSequence;
            CollectionAssert.AreEquivalent(new[]{owner},(IEnumerable<TrafficIntentKey>)frozen);
            core.Tick(.5f,false);var debt=(float)D1Read(core,incoming,"WaitRemaining");
            var queries=core.QueriesConsumed(incoming);var ownerQueries=core.QueriesConsumed(owner);var beforeCalls=calls;
            world=Snapshot(2,true);core.SetSnapshot(world);
            if(known)
            {
                Assert.That(D1Read(core,owner,"JourneyPermit"),Is.SameAs(source));Assert.That(D1Read(core,owner,"Leg"),Is.SameAs(originalLeg));
                Assert.That(D3ReadField(originalLeg,"Stamp"),Is.EqualTo(stamp));Assert.That(D3ReadField(originalLeg,"Bound"),Is.EqualTo(true));
                Assert.That(core.HasActiveGrant(owner),Is.True);
                var actualPath=(Vector3[])D1Read(core,owner,"CurrentPath");var physical=world.Bodies.Single(b=>b.Owner.Equals(obstacle));
                Assert.That(actualPath.Length,Is.GreaterThan(1));
                Assert.That(CustomerRoutePlanner.IsClear(actualPath,new[]{physical.Position},.8f),Is.EqualTo(mode!="blocked"),
                    "PREMISE: the new stationary body blocks the SAME currently Bound route, not an old prefix or another source");
                Assert.That(CustomerRoutePlanner.IsClear(new[]{target},new[]{physical.Position},.8f),Is.True,
                    "PREMISE: obstacle does not directly occupy the waiter's endpoint");
            }
            var hint=world.Bodies.Single(b=>b.Owner.Equals(owner));
            Assert.That(hint.Enabled&&hint.ActorActive&&hint.IndependentlyProgressing,Is.True);Assert.That(hint.RemainingSeconds,Is.GreaterThan(0));
            // The same production reprepare seam refreshes metadata only; the related owner event wakes the old wait.
            // 正常重证入口只刷新原snapshot；再用原owner/resource事件唤醒，不重建Entry或Frozen。
            Assert.That(CfcReprepare(core,original,Request(incoming,Origin,target,world,frame:11,resource:"prospective-parking",seconds:20),out var refreshed),Is.True);
            Assert.That(refreshed,Is.SameAs(original));
            core.NotifyChanged(owner,resource);core.ProcessReady(12);var actual=core.GetDecision(incoming);
            Assert.That(((System.Collections.IDictionary)D3ReadField(core,"entries"))[incoming],Is.SameAs(entry));
            Assert.That(D1Read(core,incoming,"FrozenOwners"),Is.SameAs(frozen));Assert.That(D1Read(core,incoming,"FrozenResources"),Is.SameAs(pool));
            Assert.That(D1Read(core,incoming,"FirstFrame"),Is.EqualTo(age));Assert.That(actual.RequestSequence,Is.EqualTo(sequence));
            Assert.That((float)D1Read(core,incoming,"WaitRemaining"),Is.LessThanOrEqualTo(debt));
            Assert.That(core.QueriesConsumed(incoming),Is.EqualTo(queries));Assert.That(core.QueriesConsumed(owner),Is.EqualTo(ownerQueries));Assert.That(calls,Is.EqualTo(beforeCalls));
            Assert.That(actual.AcquiredSequence,Is.Zero);Assert.That(core.TryCommit(actual),Is.False);Assert.That(core.HasActiveGrant(incoming),Is.False);
            if(mode=="blocked")
            {
                Assert.That(actual.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),
                    "FEATURE: a known original Bound route fails current independent clearance; its own finite body hint cannot restore that release promise: "+actual.Reason);
                Assert.That(actual.Reason,Is.EqualTo("no-independent-finite-release-or-cycle"));Assert.That(actual.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            }
            else
            {
                Assert.That(actual.Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic),actual.Reason);
                Assert.That(actual.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.None));Assert.That(actual.Blockers.Any(b=>b.Owner.Equals(owner)),Is.True);
            }
        }


        private static TrafficWorldSnapshot World(long version = 1, long bodies = 1,
            TrafficBodyFact[] actors = null, TrafficParkingFact[] parking = null)
            => new TrafficWorldSnapshot(version, bodies, actors, parking);
        private static ServiceTrafficCoordinator Coordinator(TrafficWorldSnapshot world = null,
            int frameBudget = 128, int intentBudget = 16384,
            Func<Vector3, Vector3, IReadOnlyList<Vector3>> query = null, float waitSeconds = 10)
            => new ServiceTrafficCoordinator("scene", 1, 7, world ?? World(),
                query ?? ((from, to) => new[] { from, to }), frameBudget, intentBudget, waitSeconds);
        private static TrafficRequest Request(TrafficIntentKey key, Vector3 start, Vector3 goal,
            TrafficWorldSnapshot world = null, int frame = 1, Vector3[] journey = null,
            TrafficRouteRequirement[] requirements = null, TrafficNativeStamp stamp = default,
            string resource = "lane", bool independent = true, float seconds = 20,
            TrafficDecisionKind? provenFailure = null)
            => new TrafficRequest(key, frame, world ?? World(), start, goal, .4f, resource,
                journey, requirements, stamp, independent, seconds, provenFailure);
        private static TrafficDecision Grant(ServiceTrafficCoordinator coordinator, TrafficRequest request, bool parking = false)
        {
            if (parking) coordinator.EvaluateParking(request); else coordinator.EvaluateMovement(request);
            coordinator.ProcessReady(request.RequestedFrame);
            var decision = coordinator.GetDecision(request.Intent);
            Assert.That(decision.Kind, Is.EqualTo(TrafficDecisionKind.Granted), decision.Reason);
            Assert.That(coordinator.TryCommit(decision), Is.True, "prepared permission must become committed");
            return decision;
        }

        // A hint only filters current endpoints before Submit; the normal Core decision remains authoritative.
        // 模型通过真实 Evaluate/Commit/CompleteLeg 形成占位，不写 private Entry 或伪造 permission。
        private static bool ParkingEndpointHint(ServiceTrafficCoordinator coordinator,TrafficRequest request)
            =>D3InvokeBool(coordinator,"IsParkingEndpointAvailable",request);

