            Assert.That(f.Confirm(receipt,true),Is.False);Assert.That(f.Begin(receipt,f.Replacement(generation:3),out _),Is.False);
            if(consume){Assert.That(f.Read(f.Next,"Retired"),Is.EqualTo(true));Assert.That(f.Core.GetDecision(f.Next).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));}
            f.Core.ProcessReady(500);Assert.That(f.Core.GetDecision(f.Parent).FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
            Assert.That(f.Calls,Is.EqualTo(calls));Assert.That(f.World.Bodies.Any(body=>ReferenceEquals(body.ActorLife,f.Actor)),Is.True,"Retirement does not delete the actual model body");
        }
