        [TestCase("apply-false")]
        [TestCase("apply-throw")]
        [TestCase("stale-canonical")]
        public void FailedProvisionalCommitWakesWaiterToUseFreedSpace(string failure)
        {
            var coordinator = Coordinator(); var a = Key("a"); var b = Key("b");
            var owner = new CanonicalOwner { FailAfterWrite = failure == "apply-false", ThrowAfterWrite = failure == "apply-throw" };
            var mutation = owner.Prepare();
            coordinator.EvaluateMovement(Request(a, P(-2), P(2)));
            coordinator.EvaluateMovement(Request(b, P(0, -2), P(0, 2)));
            coordinator.ProcessReady(1);
            Assert.That(coordinator.GetDecision(b).Kind, Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            if (failure == "stale-canonical") owner.ExternalChange();
            Assert.That(coordinator.TryCommit(coordinator.GetDecision(a), mutation), Is.False);
            Assert.That(owner.Value, Is.Zero);
            Assert.That(coordinator.DrainReady(), Does.Contain(b), "released provisional space must trigger a targeted reevaluation");
            coordinator.ProcessReady(2);
            Assert.That(coordinator.GetDecision(b).Kind, Is.EqualTo(TrafficDecisionKind.Granted));
        }

