        [Test]
        public void FreshEquivalentRequirementsDoNotRestartDeferredNativeCursor()
        {
            var edges=new List<string>();var key=Key("a");
            var coordinator=Coordinator(frameBudget:1,intentBudget:500,query:(a,b)=>
            {edges.Add(a.ToString("R")+">"+b.ToString("R"));return new[]{a,b};});
