            f.Coordinator.SetSnapshot(f.World);f.Coordinator.NotifyChanged(blocker,"body");
            Assert.That(f.Prepare(generation:9),Is.SameAs(terminal));Assert.That(f.Coordinator.TryCommit(terminal),Is.False);
        }

