        [Test] public void FastUnissuedLegWaitRejectsReentrantClaimRetirementWithoutRestoringOldObjects()
        {
            var marker=new FastPendingClaimMarker();var f=FastPendingUnissuedLeg(out var blocker,out var life,out _,out var claim,marker);
            f.World=World(2,3,new[]{new TrafficBodyFact(f.Key,Origin,.4f,actorLife:f.Actor),
                new TrafficBodyFact(blocker,f.End+P(.01f),.4f,independentlyProgressing:true,remainingSeconds:13,actorLife:life)},new[]{claim});
            f.Coordinator.SetSnapshot(f.World);var queries=f.Coordinator.QueriesConsumed(f.Key);
            marker.DuringCompare=()=>f.Coordinator.Retire(f.Key);
            var result=f.Prepare(generation:9);
            Assert.That(marker.Calls,Is.GreaterThan(0),"PRODUCT: original own-claim checkpoint must actually be consulted");
            Assert.That(result.Kind,Is.EqualTo(TrafficDecisionKind.StaleContext));Assert.That(f.Coordinator.GetDecision(f.Key).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
            Assert.That(f.Read("Retired"),Is.True);Assert.That(f.Read("Leg"),Is.Null);Assert.That(f.Read("Request"),Is.Null);
            Assert.That(f.Coordinator.QueriesConsumed(f.Key),Is.EqualTo(queries));Assert.That(f.Coordinator.HasActiveGrant(f.Key),Is.False);
        }
        private sealed class FastPendingClaimMarker:ITrafficClaimCheckpoint
        {
            internal object Owner;internal long Version;internal Action DuringCompare;internal int Calls;
            public object CanonicalOwner=>Owner;public string ResourceId=>"fast-own-slot";public long CapturedOwnerVersion=>Version;
            public bool IsSameCurrentClaim(ITrafficClaimCheckpoint current)
            {Calls++;DuringCompare?.Invoke();return ReferenceEquals(this,current);}
        }

        private sealed class LegFixture
        {
            internal readonly ServiceTrafficCoordinator Coordinator;
            internal readonly TrafficIntentKey Key=ServiceTrafficCoordinatorTests.Key("leg-actor");
            internal readonly object Actor=new object();
            internal TrafficWorldSnapshot World;
            internal readonly TrafficDecision Journey;
            internal readonly TrafficRouteProof Outward,Home;
            internal int Frame=1;
            internal Vector3 End=>Outward.Waypoints[0];
            internal LegFixture(Func<Vector3,Vector3,IReadOnlyList<Vector3>> query=null)
            {
                World=ServiceTrafficCoordinatorTests.World(actors:new[]{new TrafficBodyFact(Key,Origin,.4f,actorLife:Actor)});
                Coordinator=ServiceTrafficCoordinatorTests.Coordinator(World,query:query);
                var requirements=new[]{
                    new TrafficRouteRequirement("outward",Origin,P(4),.8f,new[]{P(2)},selectedJourney:true,avoidProposedParking:false),
                    new TrafficRouteRequirement("home",P(4),P(8),.8f,selectedJourney:true,avoidProposedParking:false),
                    new TrafficRouteRequirement("capability",P(20),P(24),.8f,avoidProposedParking:false)};
                Coordinator.EvaluateParking(Request(Key,Origin,Origin,World,requirements:requirements,resource:"canonical-parking"));
                for(var i=0;i<100;i++)
                {
                    Coordinator.ProcessReady(Frame++);
                    if(Coordinator.GetDecision(Key).Kind!=TrafficDecisionKind.DeferredByBudget)break;
                }
                Journey=Coordinator.GetDecision(Key);
                Assert.That(Journey.Kind,Is.EqualTo(TrafficDecisionKind.Granted),Journey.Reason);
                Assert.That(Coordinator.TryCommit(Journey),Is.True);
                Outward=Journey.ProofRoutes.Single(p=>p.ResourceId=="outward");
                Home=Journey.ProofRoutes.Single(p=>p.ResourceId=="home");
                Assert.That(Outward.LegEnds.Count,Is.GreaterThan(1),"Fixture premise: canonical retained multi-leg proof");
            }
            internal TrafficDecision Prepare(int index=0,int generation=1,Vector3? start=null,float arrivalTolerance=.05f)
            {
                if(index>0)
                {
                    World=ServiceTrafficCoordinatorTests.World(1,World.BodyVersion+1,
                        new[]{new TrafficBodyFact(Key,start??Origin,.4f,actorLife:Actor)});
                    Coordinator.SetSnapshot(World);
                }
                return Coordinator.PrepareLeg(Journey,"outward",index,Actor,generation,World,start??Origin,arrivalTolerance,Frame);
            }
            internal TrafficDecision CommitPrepared()
            {
                Coordinator.ProcessReady(Frame++);var decision=Coordinator.GetDecision(Key);
                Assert.That(decision.Kind,Is.EqualTo(TrafficDecisionKind.Granted),decision.Reason);
                Assert.That(Coordinator.TryCommit(decision),Is.True,"Current leg needs its own committed permission");return decision;
            }
            internal void Start()
            {
                Assert.That(Prepare().Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));CommitPrepared();
            }
            internal object Read(string name)
            {
                const System.Reflection.BindingFlags flags=System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic;
                var entries=(System.Collections.IDictionary)typeof(ServiceTrafficCoordinator).GetField("entries",flags).GetValue(Coordinator);
                var entry=entries[Key];return entry.GetType().GetField(name,flags).GetValue(entry);
            }
        }

        [TestCase(0)]
        [TestCase(1)]
        public void CompletedMilestoneHoldsExactWakeUntilCommittedFiniteSuccessor(int nativeRetryCount)
        {
            var f=new HandoffFixture();var waiterQueries=f.Coordinator.QueriesConsumed(f.Waiter);
            Assert.That(f.SourceSnapshot.Parking,Is.Empty,"Journey planning precedes actual pickup publication");
            Assert.That(((TrafficRequest)f.Read(f.Owner,"Request")).Snapshot.Parking.Single(),Is.SameAs(f.OriginalClaim),
                "Provenance comes from the actual committed strict leg's stored snapshot");
            var pending=f.Begin(nativeRetryCount);
            Assert.That(f.ConfirmCalls,Is.EqualTo(1));Assert.That(f.LegCompleted,Is.True);
            Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.False);Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            f.Coordinator.NotifyChanged(f.Owner,f.Resource);f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.DrainReady(),Is.Empty,"No visible wake before the handoff is complete");
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(waiterQueries));
            var successor=f.Successor();var publications=0;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>
            {
                publications++;Assert.That(f.Frozen(f.Waiter),Does.Contain(successor.Intent));
                Assert.That(f.Frozen(f.Waiter),Has.No.Member(f.Owner));
                Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.True);
                Assert.That(f.Coordinator.GetDecision(f.Owner).Kind,Is.EqualTo(TrafficDecisionKind.Cancelled));
                f.PublishSuccessor(successor.Intent);
            }),Is.True,"Only the same owned obligation may atomically hand off to a finite committed successor");
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True,
                "The published ownership-only snapshot must leave the same committed strict leg immediately issuable");
            var saved=((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot;
            Assert.That(saved,Is.SameAs(f.World),"Only the actual publisher snapshot may authenticate the next completion");
            var savedClaim=saved.Parking.Single();Assert.That(savedClaim.Owner,Is.EqualTo(successor.Intent));
            Assert.That(savedClaim.BusinessOwner,Is.SameAs(f.Business));Assert.That(savedClaim.ReleaseObligation,Is.SameAs(f.Obligation));
            Assert.That(savedClaim,Is.SameAs(f.World.Parking.Single()));
            Assert.That(publications,Is.EqualTo(1));Assert.That(f.Coordinator.DrainReady(),Does.Contain(f.Waiter));
            f.Coordinator.ProcessReady(f.Frame++);
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            Assert.That(f.Coordinator.GetDecision(f.Waiter).Blockers.All(b=>b.Owner.Equals(successor.Intent)),Is.True,
                "The woken waiter rechecks the same physical obligation under its verified successor");
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>publications++),Is.False);
            Assert.That(publications,Is.EqualTo(1));Assert.That(f.Coordinator.CompleteLeg(f.Owner,f.Actor,f.Stamp,f.End),Is.False);
        }

        [TestCase("other-body-position")]
        [TestCase("canonical-version")]
        public void HandoffPublicationCannotRebindUnrelatedChangedFacts(string change)
        {
            var f=new HandoffFixture();f.IncludeOtherBody();var pending=f.Begin();var successor=f.Successor();
            var before=((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot;
            var queries=f.Coordinator.QueriesConsumed(successor.Intent);var claimVersion=f.Canonical.Version;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),
                publish:()=>f.PublishSuccessor(successor.Intent,change)),Is.True,
                "A later publication change cannot undo the actual joint commit or collection");
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.False,
                "Owner-tag transfer cannot authorize changed physical or canonical facts");
            Assert.That(((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot,Is.SameAs(before));
            Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(queries));
            Assert.That(f.Canonical.Value,Is.EqualTo(2));Assert.That(f.CurrentBodyPresent,Is.True);
            if(change=="other-body-position")
                Assert.That(f.World.Bodies.Single(b=>b.Owner.ActorId=="unrelated-body").Position,Is.EqualTo(P(21)));
            else Assert.That(f.Canonical.Version,Is.EqualTo(claimVersion+1));
        }

        [Test] public void VerifiedHandoffPreservesWaiterAgeQueriesBudgetAndStartsNewSuccessorAge()
        {
            var f=new HandoffFixture();var phaseAge=f.Read(f.Waiter,"FirstFrame");var sequence=f.Coordinator.GetDecision(f.Waiter).RequestSequence;
            var queries=f.Coordinator.QueriesConsumed(f.Waiter);var originalBudget=(float)f.Read(f.Waiter,"WaitRemaining");
            var pending=f.Begin();f.Coordinator.Tick(2,false);f.Coordinator.Tick(100,true);f.Coordinator.Tick(0,false);
            Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(originalBudget-2));
            var successor=f.Successor();var successorQueries=f.Coordinator.QueriesConsumed(successor.Intent);
            Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var source),Is.True);
            Assert.That(source,Is.SameAs(f.ExpectedContinuationSource));
            Assert.That(source.ProofRoutes.Single().ExpandedPath.Count,Is.GreaterThan(1));
            Assert.That(f.Receipt().AuthorizesSuccessor(successor.Intent,source,f.CollectionFrame),Is.True);
            Assert.That(f.Receipt().AuthorizesSuccessor(successor.Intent,source,f.CollectionFrame-1),Is.False);
            Assert.That(f.Read(successor.Intent,"FirstFrame"),Is.EqualTo(f.CollectionFrame));
            Assert.That((int)f.Read(successor.Intent,"FirstFrame"),Is.GreaterThan((int)f.Read(f.Owner,"FirstFrame")));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            Assert.That(f.Read(f.Waiter,"FirstFrame"),Is.EqualTo(phaseAge));
            Assert.That(f.Coordinator.GetDecision(f.Waiter).RequestSequence,Is.EqualTo(sequence));
            Assert.That(f.Coordinator.QueriesConsumed(f.Waiter),Is.EqualTo(queries));
            Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(successorQueries));
            Assert.That(f.Read(f.Waiter,"WaitRemaining"),Is.EqualTo(originalBudget-2));
            Assert.That(f.Coordinator.GetDecision(successor.Intent).AcquiredSequence,Is.GreaterThan(f.Source.AcquiredSequence));
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,5),Is.True);
            Assert.That(f.Coordinator.BindLeg(successor.Intent,f.Actor,new TrafficNativeStamp(91,5)),Is.True,
                "Lawful collection-time source reaches a real kernel strict committed/bound leg");
        }

        [TestCase("life")]
        [TestCase("business")]
        [TestCase("release")]
        [TestCase("canonical")]
        [TestCase("resource")]
        [TestCase("copied-original-claim")]
        [TestCase("matching-forged-claims")]
        public void HandoffRejectsForeignActorLifeBusinessOwnerCanonicalOwnerOrResource(string mismatch)
        {
            var f=new HandoffFixture();var pending=f.Begin();var successor=f.Successor();var receipt=f.Receipt();
            if(mismatch=="life")receipt.ActorLife=new object();
            if(mismatch=="business")receipt.BusinessOwner=new object();
            if(mismatch=="release")receipt.ReleaseObligation=new object();
            if(mismatch=="canonical")receipt.CurrentClaim=f.Claim(canonical:new object());
            if(mismatch=="resource")receipt.CurrentClaim=f.Claim(resource:"unrelated-resource");
            if(mismatch=="copied-original-claim")receipt.OriginalClaim=f.Claim(version:f.OriginalClaim.OwnerVersion);
            if(mismatch=="matching-forged-claims")
            {
                var inventedBusiness=new object();var inventedRelease=new object();var inventedOwner=new object();
                receipt.BusinessOwner=inventedBusiness;receipt.ReleaseObligation=inventedRelease;
                receipt.OriginalClaim=receipt.CurrentClaim=f.Claim(canonical:inventedOwner,business:inventedBusiness,release:inventedRelease);
            }
            // Even an adapter claiming currentness cannot replace provenance already stored with the real leg.
            receipt.TrustCurrent=true;var published=false;
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,receipt,publish:()=>published=true),Is.False);
            Assert.That(published,Is.False);Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            Assert.That(f.Frozen(f.Waiter),Has.No.Member(successor.Intent));Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.False);
            Assert.That(f.Canonical.Value,Is.EqualTo(2));Assert.That(f.CurrentBodyPresent,Is.True);
        }

        [TestCase("stale-then-fresh")]
        [TestCase("session")]
        [TestCase("epoch")]
        [TestCase("layout")]
        [TestCase("not-collected")]
        [TestCase("wrong-request")]
        [TestCase("wrong-generation")]
        [TestCase("wrong-actor")]
        [TestCase("not-arrived")]
        [TestCase("wrong-endpoint")]
        [TestCase("mutation-failed")]
        [TestCase("mutation-threw")]
        public void HandoffRejectsStaleVersionContextOrUncompletedMilestone(string mismatch)
        {
            var f=new HandoffFixture();
            if(mismatch=="wrong-request" || mismatch=="wrong-generation" || mismatch=="wrong-actor" ||
                mismatch=="not-arrived" || mismatch=="wrong-endpoint")
            {
                f.ArriveBody();var called=false;var stamp=mismatch=="wrong-request"?new TrafficNativeStamp(72,4):
                    mismatch=="wrong-generation"?new TrafficNativeStamp(71,5):f.Stamp;
                var original=new MovementResult(71,mismatch=="wrong-actor"?"foreign-actor":f.Owner.ActorId,
                    mismatch=="not-arrived"?MovementStatus.Failed:MovementStatus.Arrived,NavigationFailure.None,
                    NavigationFailure.None,NavigationFailure.None,mismatch=="wrong-endpoint"?P(20):f.End,0);
                Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,stamp,original,
                    ()=>{called=true;return f.Confirm();},out var rejected),Is.False);
                Assert.That(called,Is.False);Assert.That(rejected,Is.Null);Assert.That(f.LegCompleted,Is.False);return;
            }
            if(mismatch.StartsWith("mutation-",StringComparison.Ordinal))
            {
                f.ArriveBody();var calls=0;
                Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
                {
                    calls++;f.Confirm(); // A true canonical write and Native arrival cannot be fabricated away on later failure.
                    if(mismatch=="mutation-threw")throw new InvalidOperationException("milestone read failed after actual arrival");
                    return null;
                },out var rejected),Is.False);
                Assert.That(calls,Is.EqualTo(1));Assert.That(rejected,Is.Null);Assert.That(f.LegCompleted,Is.True);
                Assert.That(f.Canonical.Value,Is.EqualTo(1));Assert.That(f.CurrentBodyPresent,Is.True);
                Assert.That(f.Coordinator.HasActiveGrant(f.Owner),Is.False);
                Assert.That(f.Coordinator.GetDecision(f.Waiter).Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));return;
            }
            var pending=f.Begin();var successor=f.Successor(contextMismatch:mismatch);var receipt=f.Receipt();
            if(mismatch=="not-collected")f.Canonical.Value=1;
            if(mismatch=="stale-then-fresh")f.Canonical.ExternalChange();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,receipt),Is.False);
            Assert.That(f.Frozen(f.Waiter),Does.Contain(f.Owner));
            if(mismatch=="stale-then-fresh")
            {
                // A fresh projection rechecks the same owned claim; it cannot merely overwrite an old receipt's version.
                var firstFrame=f.Read(successor.Intent,"FirstFrame");
                var sequence=successor.RequestSequence;var acquired=successor.AcquiredSequence;var queries=f.Coordinator.QueriesConsumed(successor.Intent);
                Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var originalSource),Is.True);
                var originalProof=originalSource.ProofRoutes.Single(p=>p.ResourceId==f.Resource);
                Assert.That(f.Coordinator.DiscardPrepared(successor.Intent),Is.True);f.Refresh();
                var frame=f.Frame++;
                Assert.That(f.Coordinator.PrepareLeg(originalSource,f.Resource,0,f.Actor,5,f.World,f.End,.05f,frame).Kind,
                    Is.EqualTo(TrafficDecisionKind.DeferredByBudget),"Explicit unissued-leg reprepare retains the acquired primary source");
                f.Coordinator.ProcessReady(frame);successor=f.Coordinator.GetDecision(successor.Intent);
                Assert.That(successor.Kind,Is.EqualTo(TrafficDecisionKind.Granted));Assert.That(f.Read(successor.Intent,"FirstFrame"),Is.EqualTo(firstFrame));
                Assert.That(f.Coordinator.TryGetCommittedJourney(successor.Intent,out var retainedSource),Is.True);Assert.That(retainedSource,Is.SameAs(originalSource));
                Assert.That(retainedSource.ProofRoutes.Single(p=>p.ResourceId==f.Resource),Is.SameAs(originalProof));
                Assert.That(successor.RequestSequence,Is.EqualTo(sequence));Assert.That(successor.AcquiredSequence,Is.EqualTo(acquired));
                Assert.That(f.Coordinator.QueriesConsumed(successor.Intent),Is.EqualTo(queries),"Same actual pose reuses the retained Native-model proof");
                Assert.That(f.ReadLeg(successor.Intent,"Committed"),Is.False);Assert.That(f.ReadLeg(successor.Intent,"Bound"),Is.False);
                var fresh=f.Receipt();Assert.That(receipt.IsCurrent,Is.False);Assert.That(fresh.IsCurrent,Is.True);
                Assert.That(fresh.CurrentClaim,Is.Not.SameAs(receipt.CurrentClaim));
                Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,fresh,publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
            }
        }

