        }

        [Test] public void MultiClaimAllReleasedCompletesOnceWithoutInventingPendingGap()
        {
            var f=new MultiClaimFixture();f.Arrive();
            Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>
            {
                f.Confirm();f.Release("counter");f.Release("service");f.Release("pickup");var receipt=f.Receipt();
                foreach(var original in f.Originals)
                { Assert.That(receipt.ReadClaim(original,out var current),Is.EqualTo(TrafficPhaseClaimState.Released));Assert.That(current,Is.Null); }
                return receipt;
            },out var pending),Is.True,"PRODUCT: accepted actual completion/canonical milestone returns true even when no gap is needed");
            Assert.That(pending,Is.Null);Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.Null);
            Assert.That(f.Completed,Is.True);Assert.That(f.Read(f.Owner,"Active"),Is.False);Assert.That(f.Read(f.Owner,"Retired"),Is.False);
            Assert.That(f.Coordinator.GetDecision(f.Owner).Kind,Is.Not.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(f.CanonicalMarked,Is.True);Assert.That(f.ConfirmCalls,Is.EqualTo(1));
            Assert.That(f.Coordinator.DrainReady(),Is.EquivalentTo(f.Waiters));
            var repeated=false;
            Assert.That(f.Coordinator.CompleteLegAndBeginHandoff(f.Owner,f.Actor,f.Stamp,f.Arrival(),()=>{repeated=true;return f.Receipt();},out _),Is.False);
            Assert.That(repeated,Is.False);Assert.That(f.World.Bodies.Single().ActorLife,Is.SameAs(f.Actor));
        }

        [Test] public void MultiClaimNewParkingCannotGiveGapBornWaiterOriginalEligibility()
        {
            var f=new MultiClaimFixture();var pending=f.Begin();f.AddParking();
            var late=Key("multi-gap-born");f.Coordinator.EvaluateMovement(Request(late,P(8,-3),P(8),f.World,frame:f.Frame,seconds:8));
            f.Coordinator.ProcessReady(f.Frame++);var failed=f.Coordinator.GetDecision(late);
            Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed),"FIXTURE: no old frozen eligibility for the newly acquired parking");
            var successor=f.Successor();
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,f.Receipt(),publish:()=>f.Publish(successor.Intent)),Is.True);
            Assert.That(f.Coordinator.GetDecision(late),Is.SameAs(failed),"A true gap-born failure cannot be revived by an added claim");
            Assert.That(f.Coordinator.DrainReady(),Has.No.Member(late));f.AssertTransferred(successor.Intent,f.AllResources);
            Assert.That(f.Read(successor.Intent,"Request"),Is.TypeOf<TrafficRequest>());
            Assert.That(((TrafficRequest)f.Read(successor.Intent,"Request")).Snapshot.Parking.Any(p=>p.ResourceId==f.NewResource && p.Owner.Equals(successor.Intent)),Is.True);
            Assert.That(f.Coordinator.CanIssueLeg(successor.Intent,f.Actor,8),Is.True);
        }

        [Test] public void MultiClaimNewParkingNeedsItsOwnCurrentCanonicalAuthority()
        {
            var f=new MultiClaimFixture();var pending=f.Begin();f.AddParking();var successor=f.Successor();
            var sourceFact=f.SuccessorSnapshot.Parking.Single(p=>p.ResourceId==f.NewResource);
            Assert.That(f.AddedParking.Remove(f.Owner.ActorId),Is.True);var receipt=f.Receipt();
            Assert.That(receipt.IsCurrent,Is.True);Assert.That(receipt.ReadClaim(f.Originals[0],out _),Is.EqualTo(TrafficPhaseClaimState.Held));
            Assert.That(receipt.ReadClaim(sourceFact,out _),Is.EqualTo(TrafficPhaseClaimState.Released),"FIXTURE: canonical release happened after strict preparation; saved snapshot itself cannot authorize it");
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(pending,successor,receipt),Is.False,
                "PRODUCT: every claim that publication would relabel needs current canonical authority");
            Assert.That(f.Coordinator.HasActiveGrant(successor.Intent),Is.False);f.AssertTransferred(f.Owner,f.AllResources);
        }

