            Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(6f),"Idle must preserve the unspent six seconds, not refill eight");
            var successor=f.Successor();f.Coordinator.Tick(1,false);Assert.That(D3ReadField(state,"Remaining"),Is.EqualTo(5f));
            Assert.That(f.Coordinator.TryCommitPhaseHandoff(handle,successor,f.Receipt(),publish:()=>f.PublishSuccessor(successor.Intent)),Is.True);
