        [Test] public void IdleArrivedParkingDoesNotGrantGapBornWaiterEligibility()
        {
            var f=new HandoffFixture();f.Coordinator.Retire(f.Waiter);var handle=f.Begin();var state=f.Read(f.Owner,"PendingHandoff");
            f.Coordinator.Tick(61,false);Assert.That(f.Read(f.Owner,"PendingHandoff"),Is.SameAs(state));
            var late=Key("idle-gap-born-waiter","pickup-wait",99);f.AddWaiter(late,8,expectWait:false);
            var failed=f.Coordinator.GetDecision(late);Assert.That(failed.Kind,Is.EqualTo(TrafficDecisionKind.PlanningFailed));
            Assert.That(failed.FailureDisposition,Is.EqualTo(TrafficFailureDisposition.Terminal));
