                p.ResourceId==f.ServiceResource?actual:current.Assignment.Position,p.Radius,p.SafetyMargin,p.BusinessOwner,p.ReleaseObligation,
                semanticCheckpoint:p.ResourceId==f.PickupResource?(object)current:null)).ToArray();
