                Assert.That(Core.PrepareLeg(source,PickupResource,0,Actor,8,World,End,.05f,24).Kind,Is.EqualTo(TrafficDecisionKind.DeferredByBudget));
                Core.ProcessReady(24);var ready=Core.GetDecision(Exit);Assert.That(ready.Kind,Is.EqualTo(TrafficDecisionKind.Granted),ready.Reason);
                Assert.That(Core.TryCommitPhaseHandoff(handle,ready,Milestone,publish:()=>{bodyOwner=Exit;Refresh();}),Is.True);
