                    original.SafetyMargin,original.ActorLife,original.ActorActive);Refresh();
            }
            internal void SetActualOwnerPosition(Vector3 value){position=value;progressing=true;Refresh();}
            internal void IncludeOtherBody(){otherBodyPosition=P(20);Refresh();}
            internal void PublishSuccessor(TrafficIntentKey key,string change=null)
            {
                bodyOwner=key; // Publishing ownership is not evidence that Native movement already began.
                if(change=="other-body-position")otherBodyPosition=P(21);
                if(change=="canonical-version")Canonical.ExternalChange();
