            }
            internal void AddWaiter(TrafficIntentKey key,float seconds,bool expectWait=true)
            {
                Coordinator.EvaluateMovement(Request(key,P(2,-4),End,World,frame:Frame,seconds:seconds));Coordinator.ProcessReady(Frame++);
                if(expectWait)Assert.That(Coordinator.GetDecision(key).Kind,Is.EqualTo(TrafficDecisionKind.WaitingForTraffic));
            }
